.ds-answer-panel { font-family: "Segoe UI", "Noto Sans", sans-serif; font-size: 11pt; background: rgba(28, 29, 32, 0.9019607843137255); color: var(--ui-text, #f2f3f5); --input-background: rgb(37, 38, 41); --input-text: #F2F3F5; --button-background: #385785; --button-text: #FFFFFF; } .ds-answer-panel { height: 100%; width: 100%; display: flex; flex-direction: column; position: relative;
  border-radius: var(--radius-panel, 12px); outline: none; } .ds-panel-chrome { display: flex; align-items: center; height: 36px; flex-shrink: 0; padding: 4px 8px; gap: 4px; } .ds-panel-status { min-width: 0; flex: 1; font-size: 11px; color: var(--input-text); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; } .ds-panel-toolbar { display: flex; flex-shrink: 0; gap: 2px; opacity: 0; pointer-events: none; transition: opacity 150ms ease-out; } .ds-answer-panel:hover .ds-panel-toolbar, .ds-answer-panel:has(:focus-visible) .ds-panel-toolbar,
.ds-answer-panel:focus-visible .ds-panel-toolbar, .ds-panel-toolbar:focus-within { opacity: 1; pointer-events: auto; } .ds-panel-toolbar button { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px;
  padding: 0; border: 0; border-radius: 6px; background: var(--input-background); color: var(--input-text); } .ds-panel-toolbar button:hover:not(:disabled) { background: var(--button-background); color: var(--button-text); } .ds-panel-toolbar button:active:not(:disabled) { transform: translateY(1px); } .ds-answer-text { flex: 1; min-height: 0; margin: 0 8px 8px; padding: 4px 8px 8px; overflow-y: auto; overflow-x: hidden;
  white-space: pre-wrap; overflow-wrap: anywhere; user-select: text; cursor: text; line-height: 1.5;
  outline: none; scrollbar-width: none; } .ds-answer-text::-webkit-scrollbar { display: none; } .ds-answer-panel:focus-visible, .ds-answer-panel button:focus-visible, .ds-answer-panel [tabindex]:focus-visible { outline: 2px solid var(--ui-accent, #9ab9ed); outline-offset: 2px; } .ds-panel-toolbar button { cursor: pointer; } .ds-panel-toolbar button:disabled { opacity: .5; cursor: default; } @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; animation: none !important; } } .ds-answer-panel, .ds-answer-text, .ds-icon, .ds-panel-chrome, .ds-panel-status, .ds-panel-toolbar { box-sizing: border-box; }
